<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {useSchedulerStore} from './stores/scheduler.js'
import Icon from './components/Icon.vue'
import Modal from './components/Modal.vue'
import RosterCalendar from './components/RosterCalendar.vue'
import {uid,dateKey,addDays,dateRange,hours,actualMinutes,requiredStaff,dutyLabel,coverageGaps,availableAssignment,hasQualifiedDriver,validateBackup,reasonsFor,businessDate,weekKey,isShiftScheduled,weeklyShiftCount,leaveForAssignment} from './lib/engine.js'
const store=useSchedulerStore(),tab=ref('schedule'),modal=ref(''),moreOpen=ref(false),toast=ref(''),toastError=ref(false),busy=ref(false)
const tabs=[['schedule','排班表','calendar'],['people','人员','users'],['settings','设置','settings']]
let toastTimer,clockTimer
const clock=ref(Date.now()),today=computed(()=>businessDate(clock.value)),layout=ref('table'),calendarDay=ref('')
const refreshClock=()=>clock.value=Date.now()
onMounted(()=>{clockTimer=setInterval(refreshClock,15000);document.addEventListener('visibilitychange',refreshClock)})
const weekdays=['日','一','二','三','四','五','六'],weekValues=[1,2,3,4,5,6,0]
const monthLabel=computed(()=>`${store.currentMonth.slice(0,4)}年${Number(store.currentMonth.slice(5))}月`)
const startOfMonth=computed(()=>store.currentMonth+'-01')
const endOfMonth=computed(()=>{const [y,m]=store.currentMonth.split('-').map(Number);return dateKey(new Date(y,m,0))})
const days=computed(()=>dateRange(startOfMonth.value,endOfMonth.value)),columns=computed(()=>store.columns())
const activeStaff=computed(()=>store.staff.filter(p=>p.active!==false)),drivers=computed(()=>activeStaff.value.filter(p=>p.canDrive===true))
const unknownDrivers=computed(()=>activeStaff.value.filter(p=>typeof p.canDrive!=='boolean').length)
const monthAssignments=computed(()=>store.assignments.filter(a=>a.date.startsWith(store.currentMonth)))
const gaps=computed(()=>monthAssignments.value.length?coverageGaps(store.assignments,store.config.shifts,startOfMonth.value,endOfMonth.value,store.allRecords(clock.value),store.config,store.staff):[])
const missing=computed(()=>gaps.value.reduce((n,g)=>n+g.missing,0)),driverGaps=computed(()=>gaps.value.filter(g=>g.driverMissing).length)
const displayRecords=computed(()=>store.allRecords(clock.value))
const monthStats=computed(()=>store.stats(store.currentMonth,clock.value))
const weeklyPeople=computed(()=>store.weeklyStats(today.value,clock.value))
const currentWeek=computed(()=>weekKey(today.value))
const leavesToday=computed(()=>store.leaves.filter(l=>l.start<=today.value&&l.end>=today.value))
const monthLeaves=computed(()=>store.leaves.filter(l=>l.start<=endOfMonth.value&&l.end>=startOfMonth.value))
const leaveConflicts=computed(()=>store.assignments.filter(a=>leaveForAssignment(store.staff.find(p=>p.id===a.staffId),a)&&['done','working'].includes(store.records[a.id]?.status)))
const leaveHistory=ref(false),visibleLeaves=computed(()=>store.leaves.filter(l=>leaveHistory.value||l.end>=today.value).sort((a,b)=>a.start.localeCompare(b.start)))
const leaveForm=ref({staffId:'',start:'',end:'',reason:''})
const leaveImpact=computed(()=>!leaveForm.value.staffId||!leaveForm.value.start||!leaveForm.value.end||leaveForm.value.end<leaveForm.value.start?[]:store.assignments.filter(a=>a.staffId===leaveForm.value.staffId&&leaveForAssignment({leavePeriods:[leaveForm.value]},a)))
const leaveManualCount=computed(()=>leaveImpact.value.filter(a=>['done','working'].includes(store.records[a.id]?.status)).length)
function leaveOn(date){return store.leaves.filter(l=>l.start<=date&&l.end>=date)}
function personLeave(p){return (p.leavePeriods||[]).find(l=>l.start<=today.value&&l.end>=today.value)}
function openLeave(p=null,l=null){leaveForm.value=l?{...l}:{staffId:p?.id||'',start:today.value,end:today.value,reason:''};modal.value='leave'}
async function saveLeave(){if(await run(()=>store.saveLeave(leaveForm.value),'请假已保存，排班会自动避开'))modal.value=''}
function seatLeave(p){return crewShift.value&&leaveForAssignment(p,{date:crewForm.value.date,start:crewShift.value.start,end:crewShift.value.end})}
const postIcon=kind=>({patrol:'car',office:'office',activity:'spark',other:'file'}[kind]||'calendar')
const postColor=kind=>({patrol:'#16816c',office:'#5e72bf',activity:'#b4873b',other:'#8d69ad'}[kind]||'#728492')
const capability=p=>p?.canDrive===true?'能开车':p?.canDrive===false?'不能开车':'待确认'
const peopleSearch=ref(''),people=computed(()=>store.staff.filter(p=>(p.name+p.group).includes(peopleSearch.value)))
const deletePersonId=ref(''),deletingPerson=computed(()=>store.staff.find(p=>p.id===deletePersonId.value))
const deleteImpact=computed(()=>{const list=store.assignments.filter(a=>a.staffId===deletePersonId.value);return {assignments:list.length,records:list.filter(a=>!!store.recordFor(a,clock.value)).length,leaves:deletingPerson.value?.leavePeriods?.length||0}})
function openDeletePerson(p){deletePersonId.value=p.id;modal.value='delete-person'}
async function deletePerson(){if(await run(()=>store.deleteStaff(deletePersonId.value),'人员及关联记录已删除'))modal.value=''}

function notify(message,error=false){toast.value=message;toastError.value=error;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',6000)}
async function run(fn,message){try{await fn();if(store.persistenceError)notify(store.persistenceError,true);else if(message)notify(message);return true}catch(e){notify(e.message||'操作未完成',true);return false}}
watch(modal,v=>{if(v)toast.value=''})
function draftSettings(){const s=JSON.parse(JSON.stringify(store.config));s.shifts=s.shifts.map(p=>({...p,dateInput:(p.dates||[]).join(', ')}));return s}
function openCalendarDay(date){calendarDay.value=date;modal.value='day'}
function go(id){tab.value=id;moreOpen.value=false;if(id==='settings')settings.value=draftSettings()}
function changeMonth(n){const [y,m]=store.currentMonth.split('-').map(Number);store.currentMonth=dateKey(new Date(y,m-1+n,1)).slice(0,7);store.save()}
function setMonth(value){if(!/^\d{4}-\d{2}$/.test(value))return;store.currentMonth=value;store.save()}
function cellEntries(date,shift,all=false){return store.assignments.filter(a=>a.date===date&&a.shiftId===shift.id&&(all||availableAssignment(a,displayRecords.value))).sort((a,b)=>(a.role==='driver'?-1:1)-(b.role==='driver'?-1:1))}
function cellActive(date,shift){return cellEntries(date,shift,true).length>0||(shift.enabled!==false&&(['activity','other'].includes(shift.kind)||isShiftScheduled(shift,date)))}
function needsDriver(date,shift){const crew=cellEntries(date,shift);return shift.kind==='patrol'&&crew.length>0&&!hasQualifiedDriver(crew,store.staff,displayRecords.value)}
function personStatus(a){const r=store.recordFor(a,clock.value);return r?.source==='auto'?'自动计入':({working:'值班中',done:'已完成',leave:'请假',absent:'缺勤'}[r?.status]||'')}
const personForm=ref({}),blockedDates=ref(''),bulkNames=ref(''),bulkDrive=ref(null)
function openPerson(p=null){personForm.value=p?JSON.parse(JSON.stringify(p)):{name:'',group:'',canDrive:null,active:true,unavailableDates:[],unavailableWeekdays:[]};blockedDates.value=personForm.value.unavailableDates.join(', ');modal.value='person'}
async function savePerson(){const ok=await run(()=>{const p=personForm.value;if(typeof p.canDrive!=='boolean')throw Error('请选择能开车或不能开车');const dates=blockedDates.value.split(/[，,\s]+/).filter(Boolean);if(dates.some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d)||dateKey(new Date(`${d}T12:00:00`))!==d))throw Error('日期格式为 2026-11-09，用逗号或换行分隔');if(p.id)store.updateStaff(p.id,{...p,unavailableDates:dates});else{store.addStaff(p.name,p.group,p.canDrive);const added=store.staff.at(-1);if(dates.length||p.unavailableWeekdays.length)store.updateStaff(added.id,{...added,unavailableDates:dates,unavailableWeekdays:p.unavailableWeekdays})}},'人员已保存');if(ok)modal.value=''}
async function saveBulk(){const ok=await run(()=>{if(typeof bulkDrive.value!=='boolean')throw Error('请选择这批人员的驾驶能力');const names=[...new Set(bulkNames.value.split(/[\n,，、;；\s]+/).filter(Boolean))];const add=names.filter(n=>!store.staff.some(p=>p.name===n));if(!add.length)throw Error('没有新的人员姓名可添加');for(const name of add)store.addStaff(name,'',bulkDrive.value);notify(`已添加 ${add.length} 人，重复姓名自动跳过`)});if(ok)modal.value=''}
const crewForm=ref({date:'',shiftId:'',need:1,staffIds:[]})
const crewShift=computed(()=>columns.value.find(s=>s.id===crewForm.value.shiftId)||store.config.shifts.find(s=>s.id===crewForm.value.shiftId))
const crewRecords=computed(()=>store.assignments.filter(a=>a.date===crewForm.value.date&&a.shiftId===crewForm.value.shiftId))
function openCell(date,shift,force=false){if(!force&&!cellActive(date,shift))return;const crew=cellEntries(date,shift),need=requiredStaff(shift,date,store.config);let ordered=[...crew];if(shift.kind==='patrol'){const driver=crew.find(a=>a.role==='driver')||crew.find(a=>store.staff.find(p=>p.id===a.staffId)?.canDrive===true);ordered=driver?[driver,...crew.filter(a=>a.id!==driver.id)]:crew}
  crewForm.value={date,shiftId:shift.id,need,staffIds:Array.from({length:Math.max(need,ordered.length)},(_,i)=>ordered[i]?.staffId||'')};modal.value='crew'}
function changeCrewNeed(){const n=Number(crewForm.value.need);if(crewForm.value.staffIds.slice(n).some(Boolean)){notify('请先清除第二位人员，再改为单人巡逻',true);crewForm.value.need=crewForm.value.staffIds.length;return}crewForm.value.staffIds=Array.from({length:n},(_,i)=>crewForm.value.staffIds[i]||'')}
function optionsForSeat(i){return activeStaff.value.filter(p=>crewShift.value.kind!=='patrol'||i!==0||p.canDrive===true||p.id===crewForm.value.staffIds[i])}
function seatLocked(i){const id=crewForm.value.staffIds[i];return crewRecords.value.some(a=>a.staffId===id&&store.records[a.id]&&availableAssignment(a,displayRecords.value))}
async function saveCrew(){if(await run(()=>store.saveDutyCrew(crewForm.value),'这一格排班已保存'))modal.value=''}
const planStart=ref(''),planEnd=ref(''),plan=ref(null)
const planCounts=computed(()=>!plan.value?[]:activeStaff.value.map(p=>({name:p.name,count:weeklyShiftCount(p.id,planStart.value,plan.value.assignments,displayRecords.value)})))
function selectWeek(date){planStart.value=weekKey(date);planEnd.value=addDays(planStart.value,6);plan.value=null}
function openGenerate(){selectWeek(store.currentMonth===today.value.slice(0,7)?today.value:store.currentMonth+'-01');modal.value='generate'}
async function generate(){busy.value=true;plan.value=null;await new Promise(r=>setTimeout(r,20));await run(()=>{plan.value=store.previewPlan(planStart.value,planEnd.value)});busy.value=false}
function applyPlan(){store.applyPlan(plan.value,planStart.value,planEnd.value);modal.value='';tab.value='schedule';notify(store.persistenceError||'排班表已更新',!!store.persistenceError)}
const selectedAssignment=ref(null),recordForm=ref({})
function openRecord(a){selectedAssignment.value=a;const existing=store.recordFor(a,clock.value);recordForm.value=existing?{...existing}:{status:'done',actualStart:`${a.date}T${a.start}`,actualEnd:`${a.end<=a.start?addDays(a.date,1):a.date}T${a.end}`,breakMinutes:0,note:''};modal.value='record'}
async function saveRecord(){if(await run(()=>store.saveRecord(selectedAssignment.value.id,recordForm.value),'值班记录已保存'))modal.value=''}
const settings=ref(draftSettings())
function addPost(kind){let n=1;while(settings.value.shifts.some(s=>s.vehicleName===`巡逻车${n}`))n++;settings.value.shifts.push({id:uid(),kind,vehicleName:kind==='patrol'?`巡逻车${n}`:'',name:kind==='patrol'?'夜间巡逻':kind==='office'?'办公室值班':kind==='activity'?'活动值班':'其他值班',start:'20:00',end:'22:00',need:kind==='patrol'?2:1,days:[0,1,2,3,4,5,6],enabled:true,dates:[],dateInput:'',color:kind==='patrol'?'#167866':kind==='office'?'#6979bf':kind==='activity'?'#b28a49':'#9a78ae'})}
function saveSettings(){run(()=>{const names=new Set();for(const s of settings.value.shifts){if(['patrol','office'].includes(s.kind)){s.start='20:00';s.end='22:00'}if(['activity','other'].includes(s.kind)){s.dates=(s.dateInput||'').split(/[，,\s]+/).filter(Boolean);if(s.dates.some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d)||dateKey(new Date(d+'T12:00:00'))!==d))throw Error('活动和其他值班日期格式为 2026-11-09，用逗号分隔')}s.need=Number(s.need);if(!s.name.trim()||!s.start||!s.end||!s.days.length||!Number.isInteger(s.need)||s.need<1||s.need>100)throw Error('请填写完整的岗位、时间和人数');if(s.kind==='patrol'){s.vehicleName=s.vehicleName.trim();if(!s.vehicleName||![1,2].includes(s.need))throw Error('车辆需填写名称，人数为 1 人或 2 人');if(s.enabled&&names.has(s.vehicleName))throw Error('车辆名称不能重复');if(s.enabled)names.add(s.vehicleName)}}if(!Number.isInteger(Number(settings.value.maxShiftsPerWeek))||settings.value.maxShiftsPerWeek<0||settings.value.maxShiftsPerWeek>21)throw Error('每周上限请填 0—21 次，0 表示不限');settings.value.maxShiftsPerWeek=Number(settings.value.maxShiftsPerWeek);if(!settings.value.name.trim()||settings.value.minRestHours<0||settings.value.minRestHours>168||settings.value.maxWeeklyHours<0||settings.value.maxWeeklyHours>168)throw Error('请检查工作台名称、休息间隔和每周时长');const clean=JSON.parse(JSON.stringify(settings.value));clean.shifts=clean.shifts.map(({dateInput,...s})=>s);Object.assign(store.config,clean);store.save()},'设置已保存')}
const fileInput=ref(null),pendingImport=ref(''),excel=ref(null)
async function exportExcel(){moreOpen.value=false;await run(async()=>{const f=await store.exportExcel();if(excel.value)URL.revokeObjectURL(excel.value.url);excel.value={url:URL.createObjectURL(f.blob),name:f.name};modal.value='excel'})}
async function pickImport(e){const f=e.target.files[0];e.target.value='';if(!f)return;await run(async()=>{pendingImport.value=await f.text();validateBackup(JSON.parse(pendingImport.value));modal.value='import'})}
async function restore(){if(await run(()=>store.importData(pendingImport.value),'备份已恢复')){modal.value='';settings.value=draftSettings()}}
const confirmMessage=ref(''),confirmAction=ref(null)
function confirm(message,action){confirmMessage.value=message;confirmAction.value=action;modal.value='confirm'}
async function doConfirm(){if(await run(confirmAction.value,'操作已完成'))modal.value=''}
onUnmounted(()=>{clearTimeout(toastTimer);clearInterval(clockTimer);document.removeEventListener('visibilitychange',refreshClock);if(excel.value)URL.revokeObjectURL(excel.value.url)})
</script>

<template>
  <div class="simple-app">
    <header class="app-header"><div class="header-inner"><a class="brand" href="#" @click.prevent="go('schedule')"><span class="brand-icon"><Icon name="shield" :size="23"/></span><strong>{{store.config.name}}</strong><small>20:00—22:00 · 每周轮换</small></a><nav aria-label="主导航"><button v-for="[id,label,icon] in tabs" :key="id" :class="{active:tab===id}" @click="go(id)"><Icon :name="icon" :size="17"/>{{label}}</button></nav><div class="more-wrap"><button class="btn compact" :aria-expanded="moreOpen" @click="moreOpen=!moreOpen">更多<Icon name="chevron" class="down" :size="13"/></button><div v-if="moreOpen" class="more-menu"><button @click="moreOpen=false;modal='stats'">查看值班时长</button><button @click="moreOpen=false;store.exportData()">导出数据备份</button><button @click="moreOpen=false;fileInput.click()">从备份恢复</button></div></div></div></header>
    <main>
      <div v-if="store.persistenceError" class="notice danger">{{store.persistenceError}}<button class="text-btn" @click="store.exportData()">导出备份</button></div>
      <template v-if="tab==='schedule'">
        <div class="page-title schedule-hero"><div class="hero-copy"><span class="eyebrow"><span></span>校园守护 · 值班工作台</span><h1>校卫队值班表</h1><p>巡逻、办公室与活动安排，清楚记录每一班。</p><div class="hero-rules"><span><Icon name="clock" :size="14"/>夜间 20:00—22:00</span><span><Icon name="calendar" :size="14"/>每周轮换</span><span><Icon name="users" :size="14"/>每周最多 {{store.config.maxShiftsPerWeek||"不限"}} 次</span></div></div><div class="actions"><button class="btn" @click="openPerson()"><Icon name="plus" :size="16"/>添加人员</button><button class="btn" @click="exportExcel"><Icon name="download" :size="16"/>导出表格</button><button class="btn primary" @click="openGenerate"><Icon name="spark" :size="16"/>按周排班</button></div></div>
        <div v-if="!store.staff.length" class="notice"><Icon name="users" :size="18"/><span>先添加人员，选择谁能开车，再按周生成排班。</span><button class="text-btn" @click="openPerson()">添加第一位人员</button></div>
        <div v-else-if="unknownDrivers" class="notice"><Icon name="alert" :size="17"/><span>{{unknownDrivers}} 位人员尚未确认驾驶能力，暂不能自动安排为司机。</span><button class="text-btn" @click="go('people')">去确认</button></div>
        <div v-if="monthLeaves.length" class="leave-banner"><span class="leave-banner-icon"><Icon name="calendar" :size="18"/></span><div><strong>本月 {{monthLeaves.length}} 段请假已纳入排班</strong><span>请假期间自动避开；已有未登记班次标为请假，重新生成可补人。</span><span v-if="leaveConflicts.length" class="danger-text">{{leaveConflicts.length}} 条人工到岗或完成记录与请假重合，请核对。</span></div><button class="text-btn" @click="go('people')">管理请假<Icon name="arrow" :size="14"/></button></div>
        <div class="roster-panel"><div class="roster-toolbar"><div class="month-control"><button class="icon-btn prev" aria-label="上个月" @click="changeMonth(-1)"><Icon name="chevron" :size="17"/></button><label class="month-picker"><strong>{{monthLabel}}</strong><Icon name="calendar" :size="14"/><input type="month" :value="store.currentMonth" aria-label="排班月份" @change="setMonth($event.target.value)"/></label><button class="icon-btn" aria-label="下个月" @click="changeMonth(1)"><Icon name="chevron" :size="17"/></button><button class="text-btn" @click="setMonth(today.slice(0,7))">本月</button></div><div class="view-switch"><button :class="{active:layout==='table'}" @click="layout='table'"><Icon name="grid" :size="14"/>表格</button><button :class="{active:layout==='calendar'}" @click="layout='calendar'"><Icon name="calendar" :size="14"/>日历</button></div><span class="roster-count">{{activeStaff.length}} 人 · {{drivers.length}} 人能开车<span v-if="monthAssignments.length"> · 已排 {{monthAssignments.length}} 人次</span></span></div>
        <div v-if="missing||driverGaps" class="table-notice">当前月份缺 {{missing}} 人次<span v-if="driverGaps">，{{driverGaps}} 辆次未安排合格司机</span>。<button class="text-btn" @click="modal='gaps'">查看</button></div>
        <RosterCalendar v-if="layout==='calendar'" :month="store.currentMonth" :today="today" :columns="columns" :assignments="store.assignments" :records="displayRecords" :leaves="store.leaves" @day="openCalendarDay" @cell="(d,s)=>openCell(d,s,true)"/>
        <div v-else class="roster-scroll"><table class="roster-table" :style="{'--post-count':columns.length}"><thead><tr><th class="date-col">日期</th><th v-for="s in columns" :key="s.id" :style="{'--post-color':postColor(s.kind)}"><div class="column-name"><Icon :name="postIcon(s.kind)" :size="18"/>{{s.kind==='patrol'?s.vehicleName:s.name}}</div><small>{{s.start}}—{{s.end}}{{s.end<=s.start?' 次日':''}} · {{s.need}} 人</small></th></tr></thead><tbody><tr v-for="d in days" :key="d" :class="{weekend:[0,6].includes(new Date(d+'T12:00:00').getDay()),today:d===today}"><th class="date-col"><strong>{{Number(d.slice(5,7))}}月{{Number(d.slice(8))}}日</strong><small>周{{weekdays[new Date(d+'T12:00:00').getDay()]}}<span v-if="d===today"> · 今天</span></small><span v-if="leaveOn(d).length" class="date-leave" :title="leaveOn(d).map(l=>l.staffName).join('、')+'请假'">{{leaveOn(d).length}} 人请假</span></th><td v-for="s in columns" :key="s.id" :class="{'inactive-cell':!cellActive(d,s),'driver-gap':needsDriver(d,s)}"><button v-if="cellActive(d,s)" class="roster-cell" :aria-label="d+' '+(s.vehicleName||s.name)+' 安排与登记'" @click="openCell(d,s)"><span v-for="a in cellEntries(d,s)" :key="a.id" class="assigned-person"><span v-if="s.kind==='patrol'" class="role-tag" :class="{driver:a.role==='driver'}">{{a.role==='driver'?'司机':a.role==='partner'?'随车':'人员'}}</span><strong>{{a.staffName}}</strong><small v-if="personStatus(a)" class="record-status" :class="displayRecords[a.id]?.status">{{personStatus(a)}}</small><Icon v-if="a.locked" name="lock" :size="11" class="locked-icon"/></span><span v-if="!cellEntries(d,s).length" class="empty-cell"><Icon name="plus" :size="14"/>{{['activity','other'].includes(s.kind)&&!isShiftScheduled(s,d)?'添加值班':'待安排'}}</span><span v-else-if="cellEntries(d,s).length<requiredStaff(s,d,store.config)" class="cell-gap">缺 {{requiredStaff(s,d,store.config)-cellEntries(d,s).length}} 人</span><span v-if="needsDriver(d,s)" class="cell-gap">缺司机</span><span v-if="cellEntries(d,s,true).some(a=>!availableAssignment(a,displayRecords))" class="absence-note">有请假 / 缺勤记录</span></button><span v-else class="off-day">—</span></td></tr></tbody></table></div>
        <div class="table-footer"><span><i></i>每周轮换 · 结束后自动计入 · 记录可修改</span><span v-if="layout==='table'" class="mobile-hint">左右滑动查看全部岗位</span><span>{{store.lastSaved?'已保存 '+store.lastSaved:'数据保存在当前浏览器'}}</span></div></div>
      </template>

      <template v-if="tab==='people'"><div class="page-title"><div><h1>人员名单</h1><p>管理驾驶能力与请假日期，让每周轮换更公平。</p></div><div class="actions"><button class="btn" @click="openLeave()"><Icon name="calendar" :size="16"/>登记请假</button><button class="btn" @click="bulkNames='';bulkDrive=null;modal='bulk'">批量添加</button><button class="btn primary" @click="openPerson()"><Icon name="plus" :size="16"/>添加人员</button></div></div><section class="roster-panel"><div class="roster-toolbar"><input v-model="peopleSearch" class="search" placeholder="搜索姓名或分组" aria-label="搜索人员"/><span class="roster-count">共 {{store.staff.length}} 人，{{drivers.length}} 人能开车</span></div><div class="scroll"><table class="people-table"><thead><tr><th>姓名</th><th>驾驶能力</th><th>本周次数</th><th>分组</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in people" :key="p.id"><td><span class="person-identity"><span class="person-avatar">{{p.name.slice(-2)}}</span><button class="person-name" :aria-label="'编辑人员 '+p.name" @click="openPerson(p)">{{p.name}}</button></span></td><td><span class="capability" :class="{yes:p.canDrive===true,unknown:p.canDrive==null}">{{capability(p)}}</span></td><td>{{weeklyPeople.find(s=>s.id===p.id)?.weeklyCount||0}} / {{store.config.maxShiftsPerWeek||'不限'}}</td><td>{{p.group||'—'}}</td><td><span class="person-state" :class="{onleave:personLeave(p),inactive:p.active===false}">{{p.active===false?'已停用':personLeave(p)?'请假中':'参与排班'}}</span></td><td class="right"><button class="text-btn" @click="openLeave(p)">请假</button><button class="text-btn" @click="openPerson(p)">编辑</button><button class="text-btn danger-text" :aria-label="'删除人员 '+p.name" @click="openDeletePerson(p)"><Icon name="trash" :size="13"/>删除</button></td></tr></tbody></table></div><div v-if="!people.length" class="empty-state"><Icon name="users" :size="32"/><strong>建立你的值班队伍</strong><span>先添加人员并选择驾驶能力，就可以开始排班。</span></div></section>
        <section class="roster-panel leave-panel"><div class="roster-toolbar"><div class="section-title"><span class="section-icon"><Icon name="calendar" :size="19"/></span><div><strong>请假管理</strong><small>含开始、结束当天，排班时自动避开</small></div></div><div class="actions"><label class="inline-check history-check"><input v-model="leaveHistory" type="checkbox"/>显示已结束</label><button class="btn compact" @click="openLeave()">＋ 登记请假</button></div></div><div v-if="leaveConflicts.length" class="table-notice">{{leaveConflicts.length}} 条人工到岗或完成记录与请假重合，原记录已保留，请到排班表核对并修改。</div><div v-if="visibleLeaves.length" class="leave-list"><article v-for="l in visibleLeaves" :key="l.id" class="leave-item"><span class="person-avatar leave-avatar">{{l.staffName.slice(-2)}}</span><div class="leave-person"><strong>{{l.staffName}}<span class="leave-state" :class="{past:l.end<today}">{{l.end<today?'已结束':l.start>today?'待开始':'请假中'}}</span></strong><p>{{l.start}}<span>至</span>{{l.end}}</p><small v-if="l.reason">{{l.reason}}</small></div><div class="leave-actions"><button class="text-btn" @click="openLeave(null,l)">修改</button><button class="text-btn muted" @click="confirm('取消 '+l.staffName+' 的这段请假？取消后可重新排班，原班次的请假记录仍保留，避免补人后重复占岗。',()=>store.cancelLeave(l.staffId,l.id))">取消请假</button></div></article></div><div v-else class="empty-state leave-empty"><Icon name="calendar" :size="30"/><strong>暂无{{leaveHistory?'':'进行中或待开始的'}}请假</strong><span>有人请假时，在这里选择人员和日期即可。</span></div></section></template>

      <template v-if="tab==='settings'"><div class="page-title"><div><h1>排班设置</h1><p>巡逻与办公室固定 20:00—22:00，活动和其他值班可自定时间和日期。</p></div><button class="btn primary" @click="saveSettings"><Icon name="check" :size="16"/>保存设置</button></div><section class="roster-panel"><div class="roster-toolbar"><strong>值班岗位与时间</strong><div class="actions"><button class="btn compact" @click="addPost('patrol')">＋ 新增车辆</button><button class="btn compact" @click="addPost('office')">＋ 办公室岗位</button><button class="btn compact" @click="addPost('activity')">＋ 活动值班</button><button class="btn compact" @click="addPost('other')">＋ 其他值班</button></div></div><div class="scroll"><table class="settings-table"><thead><tr><th>岗位</th><th>名称</th><th>开始时间</th><th>结束时间</th><th>人数</th><th>启用</th></tr></thead><tbody><tr v-for="s in settings.shifts" :key="s.id"><td>{{s.kind==='patrol'?'巡逻车':s.kind==='office'?'办公室':s.kind==='activity'?'活动值班':'其他值班'}}</td><td><input v-if="s.kind==='patrol'" v-model="s.vehicleName" aria-label="车辆名称" placeholder="车辆名称或车牌" maxlength="30"/><input v-else v-model="s.name" aria-label="岗位名称" maxlength="30"/></td><td><input v-model="s.start" :disabled="['patrol','office'].includes(s.kind)" type="time" aria-label="开始时间"/></td><td><input v-model="s.end" :disabled="['patrol','office'].includes(s.kind)" type="time" aria-label="结束时间"/></td><td><select v-if="s.kind==='patrol'" v-model.number="s.need" aria-label="默认随车人数"><option :value="1">1 人</option><option :value="2">2 人</option></select><input v-else v-model.number="s.need" type="number" min="1" max="100" :aria-label="s.name+'人数'"/></td><td><input v-model="s.enabled" type="checkbox" :aria-label="'启用'+(s.vehicleName||s.name)"/></td></tr></tbody></table></div><div class="weekly-rules"><label>每人每周最多 <input v-model.number="settings.maxShiftsPerWeek" type="number" min="0" max="21" aria-label="每人每周最多次数"/> 次</label><span>按周一到周日计算；0 表示不限。办公室优先安排不会开车的人。</span></div><div class="event-date-settings"><label v-for="s in settings.shifts.filter(s=>['activity','other'].includes(s.kind))" :key="s.id">{{s.name}}安排日期<input v-model="s.dateInput" :aria-label="s.name+'安排日期'" placeholder="例如：2026-11-09, 2026-11-12"/><small>仅在这些日期参与自动排班，也可直接在日历上添加。</small></label></div><p class="section-help">结束时间早于或等于开始时间时，按次日计算。每辆车的当日人数可在排班表里单独调整。</p></section><details class="advanced"><summary>更多排班规则</summary><div class="advanced-content"><div class="form-grid"><label>工作台名称<input v-model="settings.name" maxlength="16"/></label><label>至少休息（小时）<input v-model.number="settings.minRestHours" type="number" min="0" max="168" step="0.5"/></label><label>每周最多（小时）<input v-model.number="settings.maxWeeklyHours" type="number" min="0" max="168" step="0.5"/><small>0 表示不限制</small></label></div><label class="inline-check"><input v-model="settings.onePerDay" type="checkbox"/>每人每天最多一个岗位</label><div v-for="s in settings.shifts" :key="s.id" class="weekday-row"><strong>{{s.vehicleName||s.name}}</strong><label v-for="d in weekValues" :key="d" class="inline-check"><input v-model="s.days" type="checkbox" :value="d"/>周{{weekdays[d]}}</label></div></div></details><p class="settings-note">车辆至少一人能开车，办公室优先安排不会开车的人员。班次结束后按计划时间自动计入，可事后修改。人员与记录保存在当前浏览器，可在右上角“更多”中备份。</p></template>
      <footer>排班、登记、统计，一张表就够。</footer>
    </main>
    <input ref="fileInput" type="file" hidden accept=".json,application/json" @change="pickImport"/>
    <div v-if="toast&&!modal" class="toast" :class="{error:toastError}" :role="toastError?'alert':'status'"><Icon :name="toastError?'alert':'check'" :size="18"/>{{toast}}<button class="icon-btn" aria-label="关闭提示" @click="toast=''"><Icon name="close" :size="15"/></button></div>

    <Modal v-if="modal==='leave'" :title="leaveForm.id?'修改请假':'登记请假'" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="saveLeave"><p class="form-help">选择日期范围后，系统会避开这几天的排班，跨夜班次也会检查。</p><label>请假人员<select v-model="leaveForm.staffId" required :disabled="!!leaveForm.id"><option value="">选择人员</option><option v-for="p in store.staff" :key="p.id" :value="p.id">{{p.name}}{{p.active===false?'（已停用）':''}}</option></select></label><div class="form-grid"><label>开始日期<input v-model="leaveForm.start" type="date" required/></label><label>结束日期<input v-model="leaveForm.end" type="date" :min="leaveForm.start" required/></label></div><label class="leave-reason">请假备注（选填）<textarea v-model="leaveForm.reason" rows="2" maxlength="300" placeholder="例如：事假、考试等"/></label><div class="auto-note"><strong>排班会自动避开这段时间</strong><p v-if="leaveImpact.length">涉及 {{leaveImpact.length}} 条已有排班；未登记班次将标为请假，可重新生成排班补人。</p><p v-if="leaveManualCount" class="danger-text">{{leaveManualCount}} 条人工到岗或完成记录将保留，请到排班表核对。</p><p v-else-if="!leaveImpact.length">起止日期都计入请假，之后可以修改或取消。</p></div><div class="modal-actions"><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">保存请假</button></div></form></Modal>
    <Modal v-if="modal==='delete-person'&&deletingPerson" title="删除人员" :message="toast" :error="toastError" @close="modal=''"><div class="delete-person-summary"><span class="delete-icon"><Icon name="trash" :size="22"/></span><div><strong>删除 {{deletingPerson.name}}？</strong><p>删除后，该人员将从名单移除，不再参与排班。</p></div></div><div v-if="deleteImpact.assignments||deleteImpact.leaves" class="delete-impact"><p>以下关联数据也会同时删除：</p><ul><li>{{deleteImpact.assignments}} 条排班（其中 {{deleteImpact.records}} 条已有值班或请假状态）</li><li>{{deleteImpact.leaves}} 段请假日期</li></ul><p>空出的岗位会显示缺口，可重新排班补人。</p></div><p class="form-help delete-warning">删除后无法直接撤销。可先导出数据备份，需要时通过“更多 → 从备份恢复”找回。若只想停止排班，可在“编辑 → 更多选项”中取消“参与排班”。</p><div class="modal-actions"><button type="button" class="text-btn push-left" @click="store.exportData()"><Icon name="download" :size="14"/>先导出备份</button><button type="button" class="btn" @click="modal=''">取消</button><button type="button" class="btn danger" @click="deletePerson">确认删除人员</button></div></Modal>
    <Modal v-if="modal==='person'" :title="personForm.id?'编辑人员':'添加人员'" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="savePerson"><label>姓名<input v-model="personForm.name" autofocus required maxlength="30" placeholder="输入姓名"/></label><fieldset><legend>能否开车 <span class="required">必选</span></legend><div class="radio-options"><label :class="{selected:personForm.canDrive===true}"><input v-model="personForm.canDrive" type="radio" name="drive" :value="true" required/>能开车</label><label :class="{selected:personForm.canDrive===false}"><input v-model="personForm.canDrive" type="radio" name="drive" :value="false" required/>不能开车</label></div><small>能开车：可排司机、随车或办公室；不能开车：可排随车或办公室。</small></fieldset><details class="form-details"><summary>更多选项</summary><div class="details-fields"><label>分组（选填）<input v-model="personForm.group" maxlength="30"/></label><label>不可值班日期<textarea v-model="blockedDates" rows="2" placeholder="例如：2026-11-09, 2026-11-12"/></label><div class="weekday-row"><span>固定不能值班</span><label v-for="d in weekValues" :key="d" class="inline-check"><input v-model="personForm.unavailableWeekdays" type="checkbox" :value="d"/>周{{weekdays[d]}}</label></div><label v-if="personForm.id" class="inline-check"><input v-model="personForm.active" type="checkbox"/>参与排班</label></div></details><div class="modal-actions"><button v-if="personForm.id" type="button" class="text-btn danger-text push-left" @click="openDeletePerson(personForm)"><Icon name="trash" :size="14"/>删除人员</button><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">保存人员</button></div></form></Modal>
    <Modal v-if="modal==='bulk'" title="批量添加人员" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="saveBulk"><label>姓名名单<textarea v-model="bulkNames" required rows="5" placeholder="每行一个姓名，或用空格分隔"/></label><fieldset><legend>这批人员的驾驶能力</legend><div class="radio-options"><label :class="{selected:bulkDrive===true}"><input v-model="bulkDrive" type="radio" name="bulkDrive" :value="true" required/>都能开车</label><label :class="{selected:bulkDrive===false}"><input v-model="bulkDrive" type="radio" name="bulkDrive" :value="false" required/>都不能开车</label></div><small>建议把能开车和不能开车的人员分两批添加；之后可逐人修改。</small></fieldset><div class="modal-actions"><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">添加人员</button></div></form></Modal>
    <Modal v-if="modal==='day'" :title="calendarDay+' · 当天值班'" @close="modal=''"><div class="calendar-day-list"><button v-for="s in columns.filter(s=>s.enabled!==false||cellEntries(calendarDay,s,true).length)" :key="s.id" @click="openCell(calendarDay,s,true)"><span><strong>{{s.vehicleName||s.name}}</strong><small>{{s.start}}—{{s.end}}{{s.end<=s.start?' 次日':''}}</small></span><span>{{cellEntries(calendarDay,s).map(a=>a.staffName).join('、')||'＋ 安排'}}</span><Icon name="chevron" :size="15"/></button></div></Modal>
    <Modal v-if="modal==='crew'&&crewShift" :title="crewForm.date+' · '+(crewShift.vehicleName||crewShift.name)" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="saveCrew"><p class="form-help">结束后自动计入，仍可修改。<br/>{{crewShift.start}}—{{crewShift.end}}{{crewShift.end<=crewShift.start?' 次日':''}}<span v-if="crewShift.kind==='patrol'"> · 司机必须能开车</span></p><label v-if="crewShift.kind==='patrol'">这一天安排几人<select v-model.number="crewForm.need" @change="changeCrewNeed"><option :value="1">1 人巡逻</option><option :value="2">2 人巡逻</option></select></label><label v-for="(_,i) in crewForm.staffIds" :key="i">{{crewShift.kind==='patrol'?(i===0?'司机（能开车）':'随车人员'):crewShift.kind==='office'?'办公室值班人员':crewShift.name+'人员'}}<select v-model="crewForm.staffIds[i]" :disabled="seatLocked(i)"><option value="">暂不安排</option><option v-for="p in optionsForSeat(i)" :key="p.id" :value="p.id" :disabled="!!seatLeave(p)||(crewShift.kind==='patrol'&&i===0&&p.canDrive!==true)||crewForm.staffIds.some((id,n)=>n!==i&&id===p.id)">{{p.name}}（{{capability(p)}}）{{seatLeave(p)?' · 请假中':''}}</option></select><small v-if="seatLocked(i)">已有实际记录，需先处理记录后再换人。</small></label><div v-if="crewRecords.length" class="crew-records"><h3>值班登记</h3><div v-for="a in crewRecords" :key="a.id"><span>{{a.staffName}}<small>{{personStatus(a)||'未登记'}}</small></span><button type="button" class="text-btn" @click="openRecord(a)">{{displayRecords[a.id]?'修改值班':'登记例外'}}</button></div></div><div class="modal-actions"><button type="button" class="text-btn danger-text push-left" @click="confirm('清空这一格的未登记人员？已有实际记录的人员不会直接移除。',()=>store.saveDutyCrew({...crewForm,staffIds:[]}))">清空安排</button><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">保存安排</button></div></form></Modal>
    <Modal v-if="modal==='generate'" title="按周生成排班表" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="generate"><p class="form-help">{{activeStaff.length}} 名人员，{{drivers.length}} 人能开车。每人每周最多 {{store.config.maxShiftsPerWeek||'不限'}} 次，办公室优先安排不会开车的人。</p><div class="week-shortcuts"><button type="button" class="btn compact" @click="selectWeek(today)">本周</button><button type="button" class="btn compact" @click="selectWeek(addDays(today,7))">下周</button><button type="button" class="text-btn" @click="selectWeek(addDays(planStart,-7))">前一周</button><button type="button" class="text-btn" @click="selectWeek(addDays(planStart,7))">后一周</button></div><div class="form-grid"><label>开始日期<input v-model="planStart" type="date" required @change="selectWeek(planStart)"/></label><label>结束日期<input v-model="planEnd" type="date" readonly required/></label></div><p class="form-help">每周轮换，优先安排本周次数少的人，并尽量避开上周同一天。请假日期会自动避开；已结束、手动安排和人工修改过的记录会保留。</p><div v-if="plan" class="plan-result" :class="{warning:plan.missing||plan.driverGaps||plan.overLimit?.length}"><strong>{{plan.missing||plan.driverGaps||plan.overLimit?.length?'方案已生成，请查看提示':'方案已生成，人员与司机均已安排'}}</strong><p>缺 {{plan.missing}} 人次，{{plan.driverGaps}} 辆次缺司机。已保留 {{plan.kept}} 条已有安排。</p><p v-if="plan.overLimit?.length">保留的既有班次中，有 {{plan.overLimit.length}} 个人周已超过次数上限，需手动调整；新班次不会继续加给这些人员。</p><p v-if="plan.driverGaps">没有司机时会留空该车辆，不会安排不能开车的人单独巡逻。</p></div><details v-if="plan" class="plan-fairness"><summary>查看本周次数分配</summary><div><span v-for="p in planCounts" :key="p.name">{{p.name}} <strong>{{p.count}} 次</strong></span></div></details><div class="modal-actions"><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn" :disabled="busy">{{busy?'正在排班…':plan?'重新生成':'生成方案'}}</button><button v-if="plan" type="button" class="btn primary" @click="applyPlan">保存到排班表</button></div></form></Modal>
    <Modal v-if="modal==='record'" title="值班登记" :message="toast" :error="toastError" @close="modal=''"><form @submit.prevent="saveRecord"><p v-if="recordForm.source==='auto'" class="auto-note">当前按排班时间自动计入。可修改时长、请假或缺勤，保存后优先采用你的修改。</p><p v-if="recordForm.source==='leave'" class="auto-note">该人员此时处于请假期间，未自动计入值班时长。如实际到岗，可在这里修改记录。</p><p class="record-summary"><strong>{{selectedAssignment.staffName}}</strong>{{selectedAssignment.date}} · {{dutyLabel(selectedAssignment)}}</p><label>状态<select v-model="recordForm.status"><option value="done">已完成</option><option value="working">值班中</option><option value="leave">请假</option><option value="absent">缺勤</option></select></label><template v-if="['done','working'].includes(recordForm.status)"><label>实际到岗时间<input v-model="recordForm.actualStart" type="datetime-local" required/></label><label v-if="recordForm.status==='done'">实际离岗时间<input v-model="recordForm.actualEnd" type="datetime-local" required/></label><label v-if="recordForm.status==='done'">扣除休息（分钟）<input v-model.number="recordForm.breakMinutes" type="number" min="0" required/></label></template><label>备注<textarea v-model="recordForm.note" rows="2" maxlength="1000"/></label><p v-if="recordForm.status==='done'" class="duration">实际时长 <strong>{{hours(actualMinutes(recordForm))}}</strong> 小时</p><div class="modal-actions"><button v-if="store.records[selectedAssignment.id]" type="button" class="text-btn danger-text push-left" @click="confirm('移除当前人工修改？如仍处于请假期间，会按请假处理；否则按排班时间自动计算。',()=>store.deleteRecord(selectedAssignment.id))">恢复自动计算</button><button type="button" class="btn" @click="modal=''">取消</button><button type="submit" class="btn primary">保存记录</button></div></form></Modal>
    <Modal v-if="modal==='stats'" :title="monthLabel+' · 值班时长'" wide @close="modal=''"><p class="form-help">结束后按排班时段自动计入，人工修改优先；跨夜班次按开始日期归属月份。</p><div class="scroll"><table><thead><tr><th>姓名</th><th>巡逻次数</th><th>办公室次数</th><th>活动 / 其他</th><th>完成次数</th><th>计入时长</th></tr></thead><tbody><tr v-for="p in monthStats" :key="p.id"><td>{{p.name}}</td><td>{{p.patrolCount}}</td><td>{{p.officeCount}}</td><td>{{p.activityCount}} / {{p.otherCount}}</td><td>{{p.done}}<small v-if="p.autoCount">（自动 {{p.autoCount}}）</small></td><td><strong>{{p.actual}} 小时</strong></td></tr></tbody></table></div><p v-if="!monthStats.length" class="empty-state">暂无人员或值班记录。</p></Modal>
    <Modal v-if="modal==='gaps'" title="排班缺口" @close="modal=''"><div class="gap-list"><p v-for="g in gaps" :key="g.date+g.shiftId"><span>{{g.date}} · {{g.shiftName}}</span><strong>{{g.missing?'缺 '+g.missing+' 人':''}}{{g.driverMissing?' / 缺司机':''}}</strong></p></div></Modal>
    <Modal v-if="modal==='excel'" title="排班表已生成" @close="modal=''"><p class="form-help">第一张工作表就是巡逻车与办公室合并的排班表，另外附有值班记录、时长统计、驾驶能力名单和请假记录。</p><div class="modal-actions"><button class="btn" @click="modal=''">关闭</button><a class="btn primary" :href="excel.url" :download="excel.name">下载 Excel 表格</a></div></Modal>
    <Modal v-if="modal==='import'" title="恢复数据备份" :message="toast" :error="toastError" @close="modal=''"><p class="form-help">恢复会替换当前设备的人员、排班和记录，可以先导出当前数据备份。</p><div class="modal-actions"><button class="btn" @click="store.exportData()">先导出当前数据</button><button class="btn primary" @click="restore">恢复备份</button></div></Modal>
    <Modal v-if="modal==='confirm'" title="确认操作" :message="toast" :error="toastError" @close="modal=''"><p class="form-help">{{confirmMessage}}</p><div class="modal-actions"><button class="btn" @click="modal=''">取消</button><button class="btn primary" @click="doConfirm">确认</button></div></Modal>
  </div>
</template>
